import app from 'flarum/admin/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
/**
 * The tracer: type a section, click where it is, repeat.
 *
 * Click a placed marker to remove it. Nothing reaches the server until Save,
 * so a mis-click is undone by closing the modal.
 */
export default class SeatMapTracerModal extends Modal {
  sections = {};
  loading = true;
  saving = false;
  name = '';
  oninit(vnode) {
    super.oninit(vnode);
    app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/classifieds/seatmaps/' + this.attrs.map.id
    }).then(result => {
      this.sections = result.data.sections || {};
      this.loading = false;
      m.redraw();
    });
  }
  className() {
    return 'Modal--large ClassifiedsTracer-modal';
  }
  title() {
    return app.translator.trans('flarum-classifieds.admin.seatmaps.trace_title', {
      title: this.attrs.map.title
    });
  }
  content() {
    if (this.loading) {
      return m("div", {
        className: "Modal-body"
      }, m(LoadingIndicator, null));
    }
    const names = this.names();
    return m("div", {
      className: "Modal-body ClassifiedsTracer"
    }, m("p", {
      className: "helpText"
    }, app.translator.trans('flarum-classifieds.admin.seatmaps.trace_help')), m("div", {
      className: "ClassifiedsTracer-controls"
    }, m("input", {
      className: "FormControl ClassifiedsTracer-name",
      type: "text",
      value: this.name,
      placeholder: app.translator.trans('flarum-classifieds.admin.seatmaps.section_placeholder', {}, true),
      oninput: e => this.name = e.target.value,
      onkeydown: e => {
        // Enter must not submit the modal — the next action is a click on
        // the chart, and a closed modal loses every section placed so far.
        if (e.key === 'Enter') e.preventDefault();
      }
    }), m("span", {
      className: "ClassifiedsTracer-count"
    }, app.translator.trans('flarum-classifieds.admin.seatmaps.traced', {
      count: names.length
    }))), m("div", {
      className: "ClassifiedsTracer-canvas"
    }, m("div", {
      className: "ClassifiedsTracer-stage",
      onclick: e => this.place(e)
    }, m("img", {
      className: "ClassifiedsTracer-image",
      src: this.attrs.map.image || '',
      alt: this.attrs.map.title,
      oncreate: vnode => this.image = vnode.dom,
      onupdate: vnode => this.image = vnode.dom
    }), m("div", {
      className: "ClassifiedsTracer-markers",
      "aria-hidden": "true"
    }, names.map(name => m("button", {
      type: "button",
      className: "ClassifiedsTracer-marker",
      key: name,
      style: {
        left: this.sections[name].x * 100 + '%',
        top: this.sections[name].y * 100 + '%'
      },
      title: app.translator.trans('flarum-classifieds.admin.seatmaps.remove', {
        section: name
      }, true),
      onclick: e => {
        e.preventDefault();
        e.stopPropagation();
        delete this.sections[name];
      }
    }, name))))), m("div", {
      className: "ClassifiedsTracer-footer"
    }, m(Button, {
      className: "Button Button--primary",
      loading: this.saving,
      disabled: this.saving,
      onclick: () => this.save()
    }, app.translator.trans('flarum-classifieds.admin.seatmaps.save'))));
  }
  /** Sorted the way a stadium numbers its sections: 2, 10, 11 — not 10, 11, 2. */
  names() {
    return Object.keys(this.sections).sort((a, b) => a.localeCompare(b, undefined, {
      numeric: true
    }));
  }
  place(e) {
    const name = this.name.trim();
    if (!name) {
      /*
       * 🚨 Refuse rather than invent a name. An auto-numbered marker on the
       * wrong section is exactly the confidently-wrong star this whole feature
       * exists to avoid.
       */
      this.element.querySelector('.ClassifiedsTracer-name')?.focus();
      return;
    }
    if (!this.image) return;

    /*
     * 🚨 Measured against the IMAGE, not the page or the stage.
     *
     * getBoundingClientRect on the rendered <img> gives the box the picture
     * actually occupies at this moment, so the fraction is right whatever the
     * zoom, the scroll position or the window width — and stays right when the
     * same chart is drawn much smaller on a phone later.
     */
    const box = this.image.getBoundingClientRect();
    const x = (e.clientX - box.left) / box.width;
    const y = (e.clientY - box.top) / box.height;
    if (x < 0 || x > 1 || y < 0 || y > 1) return;
    this.sections[name] = {
      x: Math.round(x * 10000) / 10000,
      y: Math.round(y * 10000) / 10000
    };
    this.name = '';
    this.element.querySelector('.ClassifiedsTracer-name')?.focus();
  }
  save() {
    if (this.saving) return;
    this.saving = true;
    app.request({
      method: 'PATCH',
      url: app.forum.attribute('apiUrl') + '/classifieds/seatmaps/' + this.attrs.map.id,
      body: {
        sections: this.sections
      }
    }).then(() => {
      this.saving = false;
      this.attrs.onsave?.();
      this.hide();
    }).catch(() => {
      this.saving = false;
      m.redraw();
    });
  }

  // The chart is traced by clicking, not by submitting; a stray Enter must not
  // close the modal and discard everything placed since it opened.
  onsubmit(e) {
    e.preventDefault();
  }
}
flarum.reg.add('ernestdefoe-classifieds', 'admin/components/SeatMapTracerModal', SeatMapTracerModal);